// v3: roster entry points, lineups and statistics. Uses only this page's demo state.
tournaments.forEach(x=>{x.players.forEach((p,i)=>p.number??='P'+String(i+1).padStart(3,'0'));x.teams.forEach((team,i)=>{team.color??=['#155e49','#b54b40','#5c7292','#796087'][i%4]})});
